// Aplica a decisão do guardrail. O guardrail tem 3 camadas, nesta ordem:
//   1) IA principal   2) IA reserva (de outro provedor, assume sozinha se a
//   principal falhar)   3) checagem simples por código, caso nenhuma IA responda.
// Assim, a falha de um modelo auxiliar nunca deixa o cliente sem resposta.

const AVISO = 'Não consegui registrar esse lançamento agora, então ele ainda NÃO foi salvo. Pode me mandar de novo, por favor? (valor, categoria e forma de pagamento)';
const JANELA_PERTO_DO_VALOR = 40; // caracteres aceitos entre o verbo e o valor em R$

// Dados originais (texto completo e o que a ferramenta realmente fez), buscados
// pelo nome do node anterior - o node da IA só devolve o texto que ele gerou.
const preparado = $('Prepara Guardrail de Lançamento').first().json;
const textoOriginal = preparado._guardrail_texto ?? '';
const toolConfirmou = preparado._guardrail_tool_confirmou === true;

// --- Camada 3: checagem simples por código (só roda se nenhuma IA respondeu) ---
// Limites de palavra: não pode haver letra ou número colado antes/depois.
const ANTES = '(?<![a-zA-Zà-úÀ-Ú0-9_])';
const DEPOIS = '(?![a-zA-Zà-úÀ-Ú0-9_])';
const VERBOS = 'lancei|registrei|adicionei|inseri|criei|alterei|atualizei|corrigi|editei';

// Tira do texto as frases que NÃO afirmam algo novo: negações ("não lancei")
// e referências ao passado ("já lancei", "lancei antes").
function semFrasesQueNaoAfirmam(texto) {
  const v = '(?:' + VERBOS + ')';
  return texto
    .replace(new RegExp(ANTES + 'n[ãa]o +(?:[^ ]+ +){0,2}?' + v + DEPOIS, 'gi'), ' ')
    .replace(new RegExp(ANTES + 'j[áa] +(?:[^ ]+ +){0,2}?' + v + DEPOIS, 'gi'), ' ')
    .replace(new RegExp(ANTES + v + ' +(?:[^ ]+ +){0,2}?(?:antes|anteriormente|ontem)' + DEPOIS, 'gi'), ' ');
}

// Só conta como afirmação se o verbo tiver um valor em R$ por perto.
function temVerboPertoDeValor(texto) {
  const re = new RegExp(ANTES + '(?:' + VERBOS + ')' + DEPOIS, 'gi');
  let m;
  while ((m = re.exec(texto)) !== null) {
    const janela = texto.slice(
      Math.max(0, m.index - JANELA_PERTO_DO_VALOR),
      m.index + m[0].length + JANELA_PERTO_DO_VALOR
    );
    if (/R[$] *[0-9]/.test(janela)) return true;
  }
  return false;
}

function afirmaSucessoPorCodigo(texto) {
  const t = semFrasesQueNaoAfirmam(String(texto));
  return temVerboPertoDeValor(t) || /pronto[!,.]? *ficou *[*]{0,2} *R[$]/i.test(t);
}

// --- Lê a resposta da IA (se houver) ---
const entrada = $input.all()[0]?.json ?? {};
let veredito = null; // true / false se a IA respondeu algo válido; null se não respondeu
if (!entrada.error && typeof entrada.text === 'string') {
  try {
    // Pega só o trecho entre a primeira "{" e a última "}" (ignora cercas de markdown).
    const t = entrada.text;
    const parsed = JSON.parse(t.slice(t.indexOf('{'), t.lastIndexOf('}') + 1));
    if (typeof parsed.afirma_sucesso === 'boolean') veredito = parsed.afirma_sucesso;
  } catch (e) {
    veredito = null;
  }
}

let afirmaSucesso;
let via;
if (veredito !== null) {
  afirmaSucesso = veredito;
  // Se o modelo reserva chegou a rodar, foi ele que salvou a checagem.
  let reservaRodou = false;
  try { reservaRodou = $('Guardrail - Modelo Reserva').isExecuted === true; } catch (e) { reservaRodou = false; }
  via = reservaRodou ? 'ia_reserva' : 'ia';
} else {
  // Nenhuma IA respondeu: só vale checar por código se a ferramenta não
  // confirmou nada (se confirmou, a resposta não tem como ser falsa).
  afirmaSucesso = toolConfirmou ? false : afirmaSucessoPorCodigo(textoOriginal);
  via = 'codigo';
}

const mentiu = afirmaSucesso && !toolConfirmou;

// Remove os campos internos de preparo antes de devolver pro resto do fluxo.
const { _guardrail_texto, _guardrail_resumo_ferramentas, _guardrail_tool_confirmou, ...resto } = preparado;

if (!mentiu) {
  return [{ json: { ...resto, output: textoOriginal, lancamento_nao_confirmado: false, guardrail_via: via } }];
}
return [{ json: { ...resto, output: AVISO, output_original_bloqueado: textoOriginal, lancamento_nao_confirmado: true, guardrail_via: via } }];
